describe('Modal Full-Screen on Small Viewports', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should display modal as full-screen on small viewports', () => {
    // Set viewport to small mobile size
    cy.viewport('360, 640');

    // Click button to open modal
    cy.get('[data-testid="open-modal-btn"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Verify modal takes up full screen height
    cy.get('[data-testid="modal-container"]').should('have.css', 'height', '100vh');

    // Verify modal takes up full screen width
    cy.get('[data-testid="modal-container"]').should('have.css', 'width', '100vw');

    // Verify modal content is visible
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');

    // Verify close button is visible
    cy.get('[data-testid="close-modal-btn"]').should('be.visible');
  });

  it('should handle modal close button click and restore normal view', () => {
    // Set viewport to small mobile size
    cy.viewport('320', '640');

    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();

    // Verify modal is visible and full screen
    cy.get('[data-testid="modal-container"]').should('be.visible');
    cy.get('[data-testid="modal-container"]').should('have.css', 'height', '100vh');

    // Click close button
    cy.get('[data-testid="close-modal-btn"]').click();

    // Verify modal is no longer visible
    cy.get('[data-testid="modal-container"]').should('not.exist');

    // Verify page content is visible again
    cy.get('[data-testid="page-content"]').should('be.visible');

    // Verify modal overlay is removed
    cy.get('[data-testid="modal-overlay"]').should('not.exist');
  });
});
